SELECT s.id, s.device, s.customer_id, t.page_values, t.pct_checkout FROM sessions s JOIN (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, ROUND((100 * SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_checkout FROM web_events WHERE event_type = 'add_to_cart' GROUP BY session_id) t ON s.id = t.session_id WHERE t.pct_checkout >= 26 ORDER BY customer_id DESC
